import pandas as pddef get_bounds_limits(df):    """    Plot histogram of column called "col"    Args:        df: pd.DataFrame that we need to analyse        col: string, col nome    Returns:        Histogram plot    """    bounds = []    for col in df.columns:        iqr = df[col].quantile(0.75) - df[col].quantile(0.25)        if iqr == 0:            iqr = 1                     q1 = df[col].quantile(0.25) - 1.5 * iqr        q3 = df[col].quantile(0.75) + 1.5 * iqr        print("Q1 - 1.5*IQR:", q1)        print("Q3 + 1.5*IQR:", q3)        bounds.append([col, max(df[col].min(), q1), min(q3, df[col].max())])    bounds = pd.DataFrame(bounds, columns=["variable", "lower_lim", "upper_lim"])    return bounds